package dev.agenttrust.gateway;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpMethod;
import java.util.Map;
import static org.junit.jupiter.api.Assertions.*;
class RoutePolicyTest {
 @Test void lifecycleRoutesHaveExactMethodsAndNoArbitrarySuffix(){String id="11111111-1111-4111-8111-111111111111";for(String kind:new String[]{"agents","datasets"}){String path="/api/versions/"+kind+"/"+id+"/lifecycle";assertTrue(RoutePolicy.allowed(path,HttpMethod.GET));assertTrue(RoutePolicy.protectedPath(path));assertFalse(RoutePolicy.allowed(path,HttpMethod.POST));assertTrue(RoutePolicy.allowed(path+"/retirement",HttpMethod.POST));assertFalse(RoutePolicy.allowed(path+"/retirement",HttpMethod.GET));assertFalse(RoutePolicy.allowed(path+"/retirement/extra",HttpMethod.POST));assertFalse(RoutePolicy.allowed(path,HttpMethod.DELETE));}assertTrue(RoutePolicy.allowed("/api/campaigns/"+id+"/version-lifecycle",HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/campaigns/"+id+"/version-lifecycle",HttpMethod.POST));}
 @Test void auditExportIsFixedReadOnlyAndQuotaProtected(){assertTrue(RoutePolicy.allowed("/api/audit-export",HttpMethod.GET));assertTrue(RoutePolicy.protectedPath("/api/audit-export"));assertFalse(RoutePolicy.allowed("/api/audit-export",HttpMethod.POST));assertFalse(RoutePolicy.allowed("/api/audit-export/foreign",HttpMethod.GET));}
 @Test void immutableReleaseRequirementsAreProtectedAndReadOnly(){String path="/api/campaigns/11111111-1111-4111-8111-111111111111/release-requirements";assertTrue(RoutePolicy.allowed(path,HttpMethod.GET));assertTrue(RoutePolicy.protectedPath(path));assertFalse(RoutePolicy.allowed(path,HttpMethod.POST));assertFalse(RoutePolicy.allowed(path+"/extra",HttpMethod.GET));}
    @org.junit.jupiter.api.Test void providerUsageIsAnAuthenticatedReadOnlyPath(){
        assertTrue(RoutePolicy.allowed("/api/provider-usage",HttpMethod.GET));
        assertTrue(RoutePolicy.protectedPath("/api/provider-usage"));
        assertFalse(RoutePolicy.allowed("/api/provider-usage",HttpMethod.POST));
        assertFalse(RoutePolicy.allowed("/api/provider-usage/foreign",HttpMethod.GET));
    }
    @org.junit.jupiter.api.Test void runHistoryNavigationIsBoundedReadOnlyAndProtected(){
        assertTrue(RoutePolicy.allowed("/api/run-history",HttpMethod.GET));
        assertTrue(RoutePolicy.allowed("/api/run-history/"+"A".repeat(84),HttpMethod.GET));
        assertTrue(RoutePolicy.protectedPath("/api/run-history"));
        assertTrue(RoutePolicy.protectedPath("/api/run-history/"+"A".repeat(84)));
        assertFalse(RoutePolicy.allowed("/api/run-history/"+"A".repeat(80),HttpMethod.GET));
        assertFalse(RoutePolicy.allowed("/api/run-history",HttpMethod.POST));
        assertFalse(RoutePolicy.allowed("/api/run-history/"+"A".repeat(84),HttpMethod.POST));
    }
 @Test void cancellationIsABoundedProtectedWriteOnly(){String id="11111111-1111-4111-8111-111111111111";for(String kind:new String[]{"runs","campaigns"}){String path="/api/"+kind+"/"+id+"/cancel";assertTrue(RoutePolicy.allowed(path,HttpMethod.POST));assertTrue(RoutePolicy.protectedPath(path));assertFalse(RoutePolicy.allowed(path,HttpMethod.GET));assertFalse(RoutePolicy.allowed(path,HttpMethod.DELETE));}}
 @Test void challengeChecksAreAuthenticatedBoundedAndReadOnly(){String id="11111111-1111-4111-8111-111111111111",path="/api/campaigns/"+id+"/gate-check/"+"a".repeat(64);assertTrue(RoutePolicy.allowed(path,HttpMethod.GET));assertTrue(RoutePolicy.protectedPath(path));assertFalse(RoutePolicy.allowed(path,HttpMethod.POST));assertFalse(RoutePolicy.allowed(path+"a",HttpMethod.GET));assertFalse(RoutePolicy.allowed(path.substring(0,path.length()-1),HttpMethod.GET));}
 @Test void auditNavigationIsBoundedReadOnlyAndQuotaProtected(){String token="A".repeat(80);assertTrue(RoutePolicy.allowed("/api/audit",HttpMethod.GET));assertTrue(RoutePolicy.allowed("/api/audit/"+token,HttpMethod.GET));assertTrue(RoutePolicy.protectedPath("/api/audit"));assertTrue(RoutePolicy.protectedPath("/api/audit/"+token));assertFalse(RoutePolicy.allowed("/api/audit",HttpMethod.POST));assertFalse(RoutePolicy.allowed("/api/audit/"+token,HttpMethod.POST));assertFalse(RoutePolicy.allowed("/api/audit/"+token+"=",HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/audit/short",HttpMethod.GET));}

 @Test void registryAndCampaignPathsAreFixedAndWritesRemainProtected(){assertTrue(RoutePolicy.allowed("/api/versions/agents",HttpMethod.POST));assertTrue(RoutePolicy.protectedPath("/api/versions/agents"));String id="11111111-1111-4111-8111-111111111111";assertTrue(RoutePolicy.allowed("/api/campaigns/"+id+"/comparison/"+id,HttpMethod.GET));assertTrue(RoutePolicy.allowed("/api/campaigns/"+id+"/reviews",HttpMethod.POST));assertTrue(RoutePolicy.allowed("/api/campaigns/"+id+"/evidence",HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/campaigns/"+id+"/evidence",HttpMethod.POST));assertFalse(RoutePolicy.allowed("/api/versions/agents/"+id,HttpMethod.POST));assertTrue(RoutePolicy.allowed("/api/campaigns/"+id+"/reviews",HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/campaigns/"+id+"/reviews",HttpMethod.DELETE));assertFalse(RoutePolicy.allowed("/api/versions/arbitrary",HttpMethod.GET));}
 @Test void developmentTrustAndReceiptRoutesAreAuthenticatedAndClosed(){String id="11111111-1111-4111-8111-111111111111";assertTrue(RoutePolicy.protectedPath("/api/gate-trust"));assertTrue(RoutePolicy.allowed("/api/gate-trust",HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/gate-trust",HttpMethod.POST));assertTrue(RoutePolicy.allowed("/api/campaigns/"+id+"/receipts",HttpMethod.POST));assertTrue(RoutePolicy.allowed("/api/campaigns/"+id+"/receipts/"+id,HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/campaigns/"+id+"/receipts/"+id,HttpMethod.POST));assertTrue(RoutePolicy.allowed("/api/campaigns/"+id+"/receipts/"+id+"/bundle",HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/campaigns/"+id+"/receipts/"+id+"/bundle",HttpMethod.POST));}
 @Test void internalAndArbitraryRoutesNeverProxy(){assertTrue(RoutePolicy.allowed("/api/runs",HttpMethod.POST));assertFalse(RoutePolicy.allowed("/internal/completions",HttpMethod.POST));assertFalse(RoutePolicy.allowed("/api/../actuator",HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/runs",HttpMethod.DELETE));assertFalse(RoutePolicy.allowed("/api/%72uns",HttpMethod.GET));}
 @Test void scopeComesFromCanonicalIdentityAndOnlyItsSessionIsForwarded(){String org="11111111-1111-4111-8111-111111111111";assertEquals(org+":"+org,RoutePolicy.quotaScope(Map.of("organizationId",org,"projectId",org)));assertThrows(IllegalArgumentException.class,()->RoutePolicy.quotaScope(Map.of("organizationId","attacker","projectId",org)));assertEquals("AGENTTRUST_STACK_SESSION=abcd.12",RoutePolicy.session("legacy=secret; AGENTTRUST_STACK_SESSION=abcd.12; unrelated=hidden"));}
 @Test void upstreamCannotChooseArbitraryRedirect(){assertTrue(GatewayController.validRedirect("/login/oauth2/code/keycloak","http://127.0.0.1:4320/"));assertFalse(GatewayController.validRedirect("/api/me","http://127.0.0.1:4320/"));assertFalse(GatewayController.validRedirect("/oauth2/authorization/keycloak","https://evil.invalid/"));}
 @Test void campaignHistoryDatasetAndBoundariesRemainReadOnlyAndProtected(){String id="11111111-1111-4111-8111-111111111111",token="A".repeat(107);for(String path:new String[]{"/api/campaign-history","/api/campaign-history/page/"+token,"/api/campaign-history/dataset/"+id,"/api/campaign-history/dataset/"+id+"/page/"+token}){assertTrue(RoutePolicy.protectedPath(path));assertTrue(RoutePolicy.allowed(path,HttpMethod.GET));assertFalse(RoutePolicy.allowed(path,HttpMethod.POST));assertFalse(RoutePolicy.allowed(path,HttpMethod.DELETE));}assertFalse(RoutePolicy.allowed("/api/campaign-history/page/"+"A".repeat(84),HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/campaign-history/organization/"+id,HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/campaign-history/dataset/"+id+"/page/"+token+"=",HttpMethod.GET));}
 @Test void readinessIsProtectedAndCannotSelectForeignScope(){assertTrue(RoutePolicy.allowed("/api/evaluation-readiness",HttpMethod.GET));assertTrue(RoutePolicy.protectedPath("/api/evaluation-readiness"));assertFalse(RoutePolicy.allowed("/api/evaluation-readiness",HttpMethod.POST));assertFalse(RoutePolicy.allowed("/api/evaluation-readiness/foreign",HttpMethod.GET));}
 @Test void versionHistoryIsKindBoundedReadOnlyAndProtected(){for(String kind:new String[]{"agents","datasets"})for(String suffix:new String[]{"","/"+"A".repeat(84)}){String path="/api/version-history/"+kind+suffix;assertTrue(RoutePolicy.allowed(path,HttpMethod.GET));assertTrue(RoutePolicy.protectedPath(path));assertFalse(RoutePolicy.allowed(path,HttpMethod.POST));}assertFalse(RoutePolicy.allowed("/api/version-history/other",HttpMethod.GET));assertFalse(RoutePolicy.allowed("/api/version-history/agents/"+"A".repeat(80),HttpMethod.GET));}
 @Test void reviewPaginationIsReadOnlyAndBounded(){String path="/api/campaigns/11111111-1111-4111-8111-111111111111/reviews/page";assertTrue(RoutePolicy.allowed(path,HttpMethod.GET));assertTrue(RoutePolicy.allowed(path+"/"+"a".repeat(79),HttpMethod.GET));assertFalse(RoutePolicy.allowed(path,HttpMethod.POST));assertFalse(RoutePolicy.allowed(path+"/"+"a".repeat(79),HttpMethod.POST));assertFalse(RoutePolicy.allowed(path+"/"+"a".repeat(80),HttpMethod.GET));}
 @Test void runReviewPaginationCannotAddMutationRoutes(){String path="/api/runs/11111111-1111-4111-8111-111111111111/reviews/page";assertTrue(RoutePolicy.allowed(path,HttpMethod.GET));assertTrue(RoutePolicy.allowed(path+"/"+"a".repeat(79),HttpMethod.GET));assertFalse(RoutePolicy.allowed(path,HttpMethod.POST));assertFalse(RoutePolicy.allowed(path+"/"+"a".repeat(79),HttpMethod.POST));assertFalse(RoutePolicy.allowed(path+"/"+"a".repeat(78),HttpMethod.GET));}
 @Test void evaluationRequestLookupIsBoundedAndReadOnly(){for(String key:new String[]{"a".repeat(8),"a".repeat(100),"11111111-1111-4111-8111-111111111111"}){String path="/api/run-requests/"+key;assertTrue(RoutePolicy.allowed(path,HttpMethod.GET));assertTrue(RoutePolicy.protectedPath(path));assertFalse(RoutePolicy.allowed(path,HttpMethod.POST));assertFalse(RoutePolicy.allowed(path,HttpMethod.DELETE));}for(String key:new String[]{"a".repeat(7),"a".repeat(101),"aaaaaaaa/other","aaaaaaaa%2fother"})assertFalse(RoutePolicy.allowed("/api/run-requests/"+key,HttpMethod.GET));}
}
